examples.template:
MonarchWidget(
    title = {{title}},
    period = {{period}},
    updatedAt = {{updatedAt|millis}},
    now = {{now|millis}},
    onViewAll = {},
    menu = { close ->
        MonarchMenuItem(text = {{menu.0.label}}, onClick = close)
        MonarchMenuItem(text = {{menu.1.label}}, onClick = close)
        if ({{menu.2.separatorBefore}}) MonarchMenuDivider()
        MonarchMenuItem(text = {{menu.2.label}}, onClick = close, destructive = {{menu.2.destructive}})
    },
) {
    MonarchText(text = {{body}})
}

